#!/usr/bin/env python3

import argparse
import json
import os
import time
import uuid
import urllib.request
import urllib.error
from datetime import datetime, timezone
from concurrent.futures import ThreadPoolExecutor, as_completed

PROMPT = "Reply with exactly one sentence about the color blue."

def make_request_payload(model_config, prompt):
    api_type = model_config.get("api_type")
    model_id = model_config.get("id")
    temperature = model_config.get("temperature", 0.7)
    max_tokens = model_config.get("max_tokens", 100)

    if api_type == "chat_completions":
        return {
            "model": model_id,
            "messages": [{"role": "user", "content": prompt}],
            "stream": True,
            "temperature": temperature,
            "max_tokens": max_tokens
        }
    elif api_type == "responses":
        return {
            "model": model_id,
            "input": prompt,
            "stream": True,
            "temperature": temperature,
            "max_tokens": max_tokens
        }
    else:
        raise ValueError(f"Unknown api_type: {api_type}")

def extract_token(chunk, api_type):
    try:
        if api_type == "chat_completions":
            choices = chunk.get("choices", [])
            if choices:
                return choices[0].get("delta", {}).get("content", "")
        elif api_type == "responses":
            if chunk.get("type") == "content_block_delta":
                return chunk.get("delta", {}).get("text", "")
    except Exception:
        pass
    return ""

def run_benchmark(model_config, prompt, timeout):
    model_id = model_config.get("id")
    api_type = model_config.get("api_type")
    base_url = model_config.get("base_url", "").rstrip("/")
    api_key_env = model_config.get("api_key_env", "")
    api_key = os.environ.get(api_key_env, "")

    result = {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None
    }

    if api_type == "chat_completions":
        endpoint = f"{base_url}/v1/chat/completions"
    elif api_type == "responses":
        endpoint = f"{base_url}/v1/responses"
    else:
        result["error"] = f"Unsupported api_type: {api_type}"
        return result

    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {api_key}",
        "x-api-key": api_key,  # For compatibility with some providers like Anthropic
        "anthropic-version": "2023-06-01"
    }

    try:
        payload = make_request_payload(model_config, prompt)
        req_data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(endpoint, data=req_data, headers=headers, method="POST")

        t_start = time.perf_counter()

        try:
            response = urllib.request.urlopen(req, timeout=timeout)
        except urllib.error.URLError as e:
            t_end = time.perf_counter()
            result["total_ms"] = (t_end - t_start) * 1000
            if isinstance(e.reason, TimeoutError):
                result["error"] = f"Connection timeout after {timeout}s"
            else:
                result["error"] = str(e)
            return result

        t_first_token = None
        first_token_val = None
        full_response_text = ""

        for line in response:
            line = line.decode("utf-8").strip()
            if line.startswith("data: "):
                data_str = line[6:].strip()
                if data_str == "[DONE]":
                    continue
                try:
                    chunk = json.loads(data_str)
                    token = extract_token(chunk, api_type)
                    if token:
                        if t_first_token is None:
                            t_first_token = time.perf_counter()
                            first_token_val = token
                        full_response_text += token
                except json.JSONDecodeError:
                    continue

        t_end = time.perf_counter()

        result["total_ms"] = round((t_end - t_start) * 1000, 2)
        if t_first_token is not None:
            result["ttft_ms"] = round((t_first_token - t_start) * 1000, 2)
            result["first_token"] = first_token_val
            result["full_response"] = full_response_text
            result["status"] = "ok"
        else:
            result["error"] = "No tokens received"

    except Exception as e:
        result["error"] = str(e)
        if result["total_ms"] is None and 't_start' in locals():
            result["total_ms"] = round((time.perf_counter() - t_start) * 1000, 2)

    return result

def main():
    parser = argparse.ArgumentParser(description="Multi-API Benchmark Harness")
    parser.add_argument("--config", required=True, help="Path to model config JSON")
    parser.add_argument("--output", default="benchmark_results.json", help="Output file path")
    parser.add_argument("--timeout", type=int, default=30, help="Per-model timeout in seconds")
    parser.add_argument("--workers", type=int, default=1, help="Number of parallel workers")

    args = parser.parse_args()

    try:
        with open(args.config, "r") as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error loading config: {e}")
        return

    models = config.get("models", [])
    if not models:
        print("No models found in config.")
        return

    results = []

    with ThreadPoolExecutor(max_workers=args.workers) as executor:
        future_to_model = {
            executor.submit(run_benchmark, model, PROMPT, args.timeout): model 
            for model in models
        }

        for future in as_completed(future_to_model):
            results.append(future.result())

    # Generate Summary
    ok_results = [r for r in results if r["status"] == "ok" and r["ttft_ms"] is not None]

    total = len(results)
    ok_count = len(ok_results)
    errors = total - ok_count

    avg_ttft = sum(r["ttft_ms"] for r in ok_results) / ok_count if ok_count > 0 else None

    if ok_results:
        fastest_model = min(ok_results, key=lambda x: x["ttft_ms"])["model_id"]
        slowest_model = max(ok_results, key=lambda x: x["ttft_ms"])["model_id"]
    else:
        fastest_model = None
        slowest_model = None

    report = {
        "run_id": str(uuid.uuid4()),
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "prompt": PROMPT,
        "results": results,
        "summary": {
            "total": total,
            "ok": ok_count,
            "errors": errors,
            "avg_ttft_ms": round(avg_ttft, 2) if avg_ttft is not None else None,
            "fastest_model": fastest_model,
            "slowest_model": slowest_model
        }
    }

    with open(args.output, "w") as f:
        json.dump(report, f, indent=2)

    print(f"Benchmark complete. Results saved to {args.output}")

if __name__ == "__main__":
    main()
